mapper.select:
SELECT u.id, u.username, u.avatarUrl, u.createTime, u.planetCode, m.matchCount, m.matchIds, ( SELECT GROUP_CONCAT(t.tagName) FROM tag t WHERE FIND_IN_SET(t.id, m.matchIds) ) AS matchTags FROM `user` u JOIN ( SELECT userId, COUNT(tagId) AS matchCount, GROUP_CONCAT(DISTINCT tagId) AS matchIds FROM user_tag WHERE tagId IN
#{tagId}
GROUP BY userId ) m ON u.id = m.userId ORDER BY m.matchCount DESC
